// Simplified Chinese GB2312-L1 + JIS-L1 kanji, Korean KS X 1001 and kana
// (Noto Sans CJK), with signed bearings and real advances. Latin and Thai
// are per UI family in fonts_script.cpp; all of it meets in gfx.cpp.
#pragma once
#include <pgmspace.h>
#include <stdint.h>

// A glyph that knows where it sits: `left` may be negative (combining marks
// reach back over the previous glyph) and `top` is from the top of the line box.
// Deliberately NOT packed: a 12-byte aligned record keeps the uint32 offset
// on a word boundary, which flash-mapped reads on the S3 want.
struct IntlGlyph {
  uint32_t off;
  int8_t left;
  int8_t top;
  uint8_t w;
  uint8_t h;
  uint8_t adv;
};

struct IntlFace {
  uint16_t box;       // line box the glyphs were baked into
  uint16_t toneDrop;  // px a lone Thai tone mark descends (measured)
  uint32_t count;
  const uint16_t* cps;      // sorted; binary-search me
  const IntlGlyph* glyphs;  // parallel to cps
  // Raw bitmaps (font packs). nullptr for the baked faces, whose bitmaps are
  // raw-deflate blocks instead (tools/intl_zip.py): block i holds raw bytes
  // zRaw[i]..zRaw[i+1] and its stream is z[zOff[i]..zOff[i+1]].
  const uint8_t* bits;
  uint32_t zBlocks;
  const uint32_t* zRaw;
  const uint32_t* zOff;
  const uint8_t* z;
};

// Largest raw block of any baked face: the size of one inflate slot.
#define INTL_ZBLOCK_MAX 4608

